import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # First few rounds: cooperate to build trust and gather information.
    if n < 4:
        # If opponent opened with a defection, don't keep being a sucker.
        if any(op == 'D' for _, op in history):
            return 'D'
        return 'C'

    opp = [op for _, op in history]
    me = [my for my, _ in history]
    opp_c = 0
    opp_d = 0
    for a in opp:
        if a == 'C':
            opp_c += 1
        else:
            opp_d += 1
    my_d = 0
    for a in me:
        if a == 'D':
            my_d += 1

    last_me = me[-1]
    last_op = opp[-1]

    # Recent behavior
    look = 10 if n >= 10 else n
    recent_op = opp[-look:]
    ro_c = 0
    ro_d = 0
    for a in recent_op:
        if a == 'C':
            ro_c += 1
        else:
            ro_d += 1
    recent_me = me[-look:]
    rm_d = 0
    for a in recent_me:
        if a == 'D':
            rm_d += 1

    # Run lengths of opponent's most recent action
    run_op = 1
    i = n - 1
    while i > 0 and opp[i - 1] == last_op:
        run_op += 1
        i -= 1

    # Count alternations in opponent's recent moves (randomness detection)
    changes = 0
    base = n - look
    for j in range(base + 1, n):
        if opp[j] != opp[j - 1]:
            changes += 1

    rounds_left = 100 - n

    # Endgame: squeeze value in final rounds.
    if rounds_left <= 1:
        # Last round: defect unless opponent is nearly certain to cooperate.
        if opp_c >= n - 1 and n >= 8:
            return 'C'
        return 'D'
    if rounds_left <= 3:
        if opp_c >= n - 1 and n >= 8 and last_op == 'C':
            return 'C'
        return 'D'
    if rounds_left <= 8:
        if opp_d == 0:
            return 'D'
        if opp_c >= 2 * opp_d:
            # mostly cooperative opponent: mixed, favor D
            return 'D' if rng.random() < 0.6 else 'C'
        return 'D'

    # Opponent never defected: exploit but slowly, keeping them cooperative.
    if opp_d == 0:
        if n >= 20 and rng.random() < 0.9:
            return 'D'
        if n >= 8 and rng.random() < 0.4:
            return 'D'
        return 'C'

    # Opponent almost always defects: defect back, rare probe.
    if opp_c <= 1:
        if n < 92 and run_op >= 8 and rng.random() < 0.1:
            return 'C'
        return 'D'

    opp_rate = opp_c / n

    # Strongly defective opponent (rate low): mostly defect but probe occasionally.
    if opp_rate < 0.2:
        if run_op >= 6 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Random-like opponent: defect since DC/DD beats CC/DD expected value against random.
    if n >= 12 and 0.38 <= opp_rate <= 0.62:
        expected_changes = (opp_c * opp_d * 2.0) / n
        if changes >= 0.7 * expected_changes and changes >= 4:
            # Against near-random, D gives (0.5*5 + 0.5*1)=3 vs C gives (0.5*3+0.5*0)=1.5.
            return 'D' if rng.random() < 0.92 else 'C'

    # Forgiveness for an isolated defection from an otherwise cooperative opponent.
    if last_op == 'D':
        if opp_rate >= 0.75 and run_op == 1 and n < 90:
            # Forgive a lone defection once, but not if we've been defecting recently.
            if rm_d <= 2:
                return 'C'
            return 'D'
        # If opponent just defected after long cooperation string, retaliate now.
        if run_op >= 2:
            # Continuous defection: stay in D unless very late.
            if rounds_left < 15 and opp_rate > 0.6 and rng.random() < 0.25:
                return 'C'
            return 'D'
        # single recent defection
        if opp_rate >= 0.55 and rng.random() < 0.35:
            return 'C'
        return 'D'

    # Opponent cooperated on last move.
    # If we defected and they still cooperated, evaluate whether to keep exploiting.
    if last_me == 'D':
        # If opponent tends to forgive & is very cooperative, exploit a bit more.
        if opp_rate >= 0.75 and ro_c >= look - 1 and n < 88:
            if rng.random() < 0.35:
                return 'D'
            return 'C'
        # Otherwise return to cooperation to rebuild mutual CC.
        return 'C'

    # Both cooperated last round.
    if ro_d == 0:
        # Long recent cooperation: mostly C, occasional probe only mid-game.
        if 20 < n < 85 and opp_rate > 0.85 and rng.random() < 0.06:
            return 'D'
        return 'C'

    # Recent mix but opponent just cooperated: cooperate, with mild opportunism.
    if opp_rate > 0.6:
        if n < 90 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # Opponent mixed moderately: reciprocate but with a bias to avoid DD lock-in.
    if ro_d >= 4 and ro_c >= 4:
        # alternating-ish: mirror last opponent
        return last_op

    if opp_rate >= 0.4:
        return 'C' if rng.random() < 0.6 else 'D'
    return 'D' if rng.random() < 0.7 else 'C'
